head.script:
            scwin.createWindowTest = function(title, id){
                wc1.createWindow( title , "" , "windowContainer_processMsgFrame_scroll_WESD-1052_(WSQ-5025)_sub.xml" , "windowTitle" , id ,"newWindow",null,null,null,null,"wframe" );
            };

    scwin.onpageload = function() {

        scwin.createWindowTest("aaa", "windowId0");
    };

    scwin.onpageunload = function() {

    };

	scwin.setVal = function() {
		WebSquare.wUnit.getJq('#wc1_subWindow0_wframe').animate({scrollTop:600},0,function(){});
	}    
	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq('#wc1_subWindow0_wframe_'+$p.id+'wc1_subWindow0_wframe_wq_processMsgComp').offset().top < 300;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setVal()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_subWindow0_wframe_trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
